{
  "title": "Discussion on tax filing, domain purchase, and low‑profit web app ideas",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Complexity of tax filing and related costs",
      "claims": [
        {
          "text": "The author paid about 1000 ₴ after re‑filing with the help of a contact, avoiding larger fines.",
          "evidence": [1]
        },
        {
          "text": "The inspector was described as corrupt and approved declarations without review.",
          "evidence": [1]
        },
        {
          "text": "The entire tax‑declaration procedure takes about an hour with Excel, at most a day per month.",
          "evidence": [5, 6]
        },
        {
          "text": "Quarterly reports must be filed correctly.",
          "evidence": [7]
        },
        {
          "text": "Mistakes arise from mis‑matching columns and numbers in the calculation.",
          "evidence": [8]
        },
        {
          "text": "A calculator only works with hryvnia‑based FOP; otherwise transactions must be converted using the daily exchange rate.",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "domain-and-calculator",
      "title": "Domain purchase and need for a calculator",
      "claims": [
        {
          "text": "Someone has not bought a domain yet.",
          "evidence": [2]
        },
        {
          "text": "A calculator (presumably for tax) is needed before money can be spent on a domain.",
          "evidence": [4]
        },
        {
          "text": "One participant doubts the domain will be bought.",
          "evidence": [9]
        },
        {
          "text": "The domain is considered a “silly thing” that won’t be useful.",
          "evidence": [10]
        }
      ]
    },
    {
      "id": "web-app-profitability",
      "title": "Viability of a low‑cost web app as a business",
      "claims": [
        {
          "text": "Web platforms are the simplest but far less profitable than Android/iOS apps.",
          "evidence": [11]
        },
        {
          "text": "SEO for a web app is poor; even on the 10th Google page the site is not found.",
          "evidence": [11]
        },
        {
          "text": "There is no external traffic from social networks or contextual ads.",
          "evidence": [11]
        },
        {
          "text": "User retention is near zero because a paywall appears within the first 10 seconds.",
          "evidence": [11]
        },
        {
          "text": "Conversion is presumed zero; the product does not simplify anything or integrate with banks or tax cabinets.",
          "evidence": [11]
        },
        {
          "text": "A successful example uses a fast delivery (<1 week) and a cross‑platform stack (Flutter).",
          "evidence": [12]
        },
        {
          "text": "The discussed project (referred to as “spa”) is viewed skeptically and likely won’t sell.",
          "evidence": [16, 17]
        },
        {
          "text": "LinkedIn audience size for such a product is shrinking, with technical/managerial posts dropping below 50%.",
          "evidence": [18]
        }
      ]
    },
    {
      "id": "scam-discussion",
      "title": "Potential scam nature of the product and password access",
      "claims": [
        {
          "text": "The app stores a single password locally as a 100% discount promo code.",
          "evidence": [20]
        },
        {
          "text": "Someone asks for the source code or password, implying it might be discoverable.",
          "evidence": [21]
        },
        {
          "text": "The reply suggests the asker never paid the 299 ₴ price.",
          "evidence": [22]
        },
        {
          "text": "Participants label the product as a “pirate” or “bandle” and mock the idea of paying for it.",
          "evidence": [23, 24, 27]
        },
        {
          "text": "One claims most LinkedIn users could hack the product easily.",
          "evidence": [28]
        },
        {
          "text": "The product is described as a “local‑first app” with USD/UAH rates updating every 5 minutes, but the paid part is just a bundle of code.",
          "evidence": [29]
        },
        {
          "text": "Another participant calls it a “free vibe‑code project” that’s nonsense and predicts nobody will buy it.",
          "evidence": [30, 31, 32, 33, 34]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Is there a viable market of at least ten people willing to pay 299 ₴ for the described app?",
      "evidence": [20]
    },
    {
      "text": "What is the actual source code or password for the app, and can it be retrieved?",
      "evidence": [21, 22]
    }
  ]
}
